-- Palmdale / Keppel members elected AT LARGE in Nov 2022: stay on the whole-district row until Dec 2026.
CREATE TEMP TABLE _hold (parent_geo text, office_id uuid, holder_pid uuid, holder_name text) ON COMMIT DROP;
