CREATE TEMP TABLE _ca0161_base ON COMMIT DROP AS
  SELECT (SELECT count(*) FROM essentials.offices_missing_terms m JOIN essentials.offices o ON o.id = m.office_id
           WHERE NOT COALESCE(o.is_vacant, false)) AS missing_unflagged;

-- ─── Pre-flight ──────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM _ta;
  IF v_n <> 110 THEN RAISE EXCEPTION 'PRE: % areas, expected 110', v_n; END IF;
  SELECT count(*) INTO v_n FROM (SELECT kind, count(*) c FROM _ta GROUP BY kind) x
   WHERE (kind, c) NOT IN (('member',103),('fresh',6),('vacant',1));
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: area kinds differ from the plan'; END IF;
  SELECT count(*) INTO v_n FROM _hold;
  IF v_n <> 6 THEN RAISE EXCEPTION 'PRE: % holdovers, expected 6', v_n; END IF;
  SELECT count(*) INTO v_n FROM (SELECT parent_geo FROM _ta GROUP BY parent_geo HAVING count(*) = 5) x;
  IF v_n <> 22 THEN RAISE EXCEPTION 'PRE: % districts with 5 areas, expected 22', v_n; END IF;

  -- each parent is ONE whole-district SCHOOL row
  SELECT count(*) INTO v_n FROM (SELECT DISTINCT parent_geo FROM _ta) x
   WHERE (SELECT count(*) FROM essentials.districts d WHERE d.geo_id = x.parent_geo AND d.district_type = 'SCHOOL' AND d.mtfcc = 'G5420') <> 1;
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % parent(s) do not resolve to one whole-district SCHOOL row', v_n; END IF;

  -- area geo_ids are free, or were created by this file
  SELECT count(*) INTO v_n FROM essentials.districts d JOIN _ta t ON t.geo_id = d.geo_id
   WHERE NOT (d.district_type = 'SCHOOL' AND d.mtfcc = 'X0002' AND d.label = t.label);
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % area geo_id(s) already used by another district', v_n; END IF;
  SELECT count(*) INTO v_n FROM essentials.geofence_boundaries b JOIN _ta t ON t.geo_id = b.geo_id
   WHERE NOT (b.mtfcc = 'X0002' AND b.source = 'lacounty_rrcc_precincts_2026' AND b.name = t.label);
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % area geo_id(s) already carry another geofence', v_n; END IF;

  -- every office of the 22 boards is accounted for (member, vacant or holdover) -- or is a fresh one of ours
  SELECT count(*) INTO v_n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.district_type = 'SCHOOL' AND (d.geo_id IN (SELECT parent_geo FROM _ta) OR d.geo_id IN (SELECT geo_id FROM _ta))
     AND o.id NOT IN (SELECT office_id FROM _ta UNION ALL SELECT office_id FROM _hold);
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % office(s) on these boards are not in the plan', v_n; END IF;

  -- member areas: the office is held by the recorded member, on its parent row or already on its area
  SELECT count(*) INTO v_n FROM _ta t
    JOIN essentials.office_current_holder och ON och.office_id = t.office_id AND och.politician_id = t.holder_pid
    JOIN essentials.offices o ON o.id = t.office_id
    JOIN essentials.districts d ON d.id = o.district_id AND d.district_type = 'SCHOOL' AND d.geo_id IN (t.parent_geo, t.geo_id)
   WHERE t.kind = 'member';
  IF v_n <> 103 THEN RAISE EXCEPTION 'PRE: % of 103 member offices are held by the recorded member', v_n; END IF;

  -- the vacant area: Little Lake's vacated seat (CA_0158), still vacant
  SELECT count(*) INTO v_n FROM _ta t JOIN essentials.offices o ON o.id = t.office_id AND o.is_vacant
   WHERE t.kind = 'vacant'
     AND NOT EXISTS (SELECT 1 FROM essentials.office_current_holder och WHERE och.office_id = t.office_id AND och.politician_id IS NOT NULL);
  IF v_n <> 1 THEN RAISE EXCEPTION 'PRE: the Little Lake TA5 seat is not the recorded vacant office'; END IF;

  -- holdovers: held by the recorded at-large member, on the parent row
  SELECT count(*) INTO v_n FROM _hold h
    JOIN essentials.office_current_holder och ON och.office_id = h.office_id AND och.politician_id = h.holder_pid
    JOIN essentials.offices o ON o.id = h.office_id
    JOIN essentials.districts d ON d.id = o.district_id AND d.geo_id = h.parent_geo AND d.district_type = 'SCHOOL';
  IF v_n <> 6 THEN RAISE EXCEPTION 'PRE: % of 6 holdover offices are held by the recorded member on the parent row', v_n; END IF;

  -- fresh office ids are free, or are ours (on the area, vacant)
  SELECT count(*) INTO v_n FROM essentials.offices o JOIN _ta t ON t.office_id = o.id
    LEFT JOIN essentials.districts d ON d.id = o.district_id
   WHERE t.kind = 'fresh' AND NOT (d.geo_id = t.geo_id AND o.is_vacant);
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % fresh office id(s) already used', v_n; END IF;

  -- no race is bound to an office that is still on a parent row and about to move
  SELECT count(*) INTO v_n FROM essentials.races r JOIN _ta t ON t.office_id = r.office_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.geo_id = t.parent_geo;
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % race(s) bound to an office this file moves', v_n; END IF;

  -- the polygons parse and are valid
  SELECT count(*) INTO v_n FROM _ta t
   WHERE NOT public.ST_IsValid(public.ST_MakeValid(public.ST_SetSRID(public.ST_GeomFromGeoJSON(t.gj), 4326)));
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % polygon(s) invalid', v_n; END IF;
END $$;

-- ─── 1. Trustee-area polygons ─────────────────────────────────────────────────────────────────────
INSERT INTO essentials.geofence_boundaries (geo_id, ocd_id, name, state, mtfcc, geometry, source, imported_at)
SELECT t.geo_id, NULL, t.label, '06', 'X0002',
       public.ST_Multi(public.ST_MakeValid(public.ST_SetSRID(public.ST_GeomFromGeoJSON(t.gj), 4326))),
       'lacounty_rrcc_precincts_2026', now()
  FROM _ta t
 WHERE NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b WHERE b.geo_id = t.geo_id AND b.mtfcc = 'X0002');

-- ─── 2. One SCHOOL sub-district per area ──────────────────────────────────────────────────────────
INSERT INTO essentials.districts (label, district_type, district_id, state, num_officials, mtfcc, geo_id,
                                  is_judicial, has_unknown_boundaries, retention, representation_basis)
SELECT t.label, 'SCHOOL', t.geo_id, 'CA', 1, 'X0002', t.geo_id, false, false, false, 'residency'
  FROM _ta t
 WHERE NOT EXISTS (SELECT 1 FROM essentials.districts d WHERE d.geo_id = t.geo_id AND d.district_type = 'SCHOOL');

-- ─── 3. Move each member's seat (and Little Lake's vacant TA5 seat) onto its area ─────────────────
UPDATE essentials.offices o
   SET district_id = sd.id, title = 'Board Member (Trustee Area ' || t.ta || ')'
  FROM _ta t
  JOIN essentials.districts pd ON pd.geo_id = t.parent_geo AND pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420'
  JOIN essentials.districts sd ON sd.geo_id = t.geo_id AND sd.district_type = 'SCHOOL'
 WHERE t.kind IN ('member','vacant') AND o.id = t.office_id AND o.district_id = pd.id;

-- ─── 4. New, vacant seats for the areas first filled by the Nov 2026 election (Palmdale, Keppel) ──
INSERT INTO essentials.offices
  (id, chamber_id, district_id, title, representing_state, representing_city, description, seats,
   normalized_position_name, partisan_type, salary, is_appointed_position, is_vacant, vacant_since,
   faces_retention_vote, role_canonical, voting_powers, representation_note)
SELECT t.office_id, o.chamber_id, sd.id, 'Board Member (Trustee Area ' || t.ta || ')', o.representing_state,
       o.representing_city, o.description, o.seats, o.normalized_position_name, o.partisan_type, o.salary,
       o.is_appointed_position, true, NULL, o.faces_retention_vote, o.role_canonical, o.voting_powers, o.representation_note
  FROM _ta t
  JOIN essentials.offices o ON o.id = t.template_office
  JOIN essentials.districts sd ON sd.geo_id = t.geo_id AND sd.district_type = 'SCHOOL'
 WHERE t.kind = 'fresh'
   AND NOT EXISTS (SELECT 1 FROM essentials.offices x WHERE x.id = t.office_id);

-- ─── 5. The at-large holdovers stay on the whole-district row, titled as such ─────────────────────
UPDATE essentials.offices o
   SET title = 'Board Member (At-Large)'
  FROM _hold h
 WHERE o.id = h.office_id AND o.title IS DISTINCT FROM 'Board Member (At-Large)';

-- ─── Post-verify gate ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_bad int;
BEGIN
  SELECT count(*) INTO v_n FROM _ta t JOIN essentials.geofence_boundaries gb ON gb.geo_id = t.geo_id AND gb.mtfcc = 'X0002'
   WHERE public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry);
  IF v_n <> 110 THEN RAISE EXCEPTION 'POST: % of 110 valid area polygons', v_n; END IF;

  -- each area: one sub-district with exactly one office; member areas held by the member, others vacant
  SELECT count(*) INTO v_n FROM _ta t
    JOIN essentials.districts sd ON sd.geo_id = t.geo_id AND sd.district_type = 'SCHOOL' AND sd.mtfcc = 'X0002'
   WHERE (SELECT count(*) FROM essentials.offices o WHERE o.district_id = sd.id) = 1
     AND EXISTS (SELECT 1 FROM essentials.offices o WHERE o.district_id = sd.id AND o.id = t.office_id
                    AND o.title = 'Board Member (Trustee Area ' || t.ta || ')')
     AND CASE WHEN t.kind = 'member'
              THEN EXISTS (SELECT 1 FROM essentials.office_current_holder och WHERE och.office_id = t.office_id AND och.politician_id = t.holder_pid)
              ELSE (SELECT o.is_vacant FROM essentials.offices o WHERE o.id = t.office_id)
                   AND NOT EXISTS (SELECT 1 FROM essentials.office_current_holder och WHERE och.office_id = t.office_id AND och.politician_id IS NOT NULL)
         END;
  IF v_n <> 110 THEN RAISE EXCEPTION 'POST: % of 110 areas carry exactly their intended seat', v_n; END IF;

  -- parents: the 20 full-partition boards keep no seat on the whole-district row; Palmdale and Keppel keep
  -- exactly their three at-large holdovers
  SELECT count(*) INTO v_bad FROM (SELECT DISTINCT parent_geo FROM _ta) x
   WHERE (SELECT count(*) FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
           WHERE d.geo_id = x.parent_geo AND d.district_type = 'SCHOOL')
         <> (SELECT count(*) FROM _hold h WHERE h.parent_geo = x.parent_geo);
  IF v_bad <> 0 THEN RAISE EXCEPTION 'POST: % parent row(s) keep the wrong number of seats', v_bad; END IF;
  SELECT count(*) INTO v_n FROM _hold h JOIN essentials.offices o ON o.id = h.office_id AND o.title = 'Board Member (At-Large)'
    JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id = h.holder_pid;
  IF v_n <> 6 THEN RAISE EXCEPTION 'POST: % of 6 holdovers held and titled as intended', v_n; END IF;

  -- coverage per district vs its own TIGER polygon (planar ratio, as CA_0144), and nothing outside it
  SELECT count(*) INTO v_bad FROM (
    SELECT t.parent_geo, max(t.tol) tol, public.ST_Union(gb.geometry) u
      FROM _ta t JOIN essentials.geofence_boundaries gb ON gb.geo_id = t.geo_id AND gb.mtfcc = 'X0002'
     GROUP BY t.parent_geo) a
    JOIN essentials.geofence_boundaries tg ON tg.geo_id = a.parent_geo AND tg.mtfcc IN ('G5400','G5410')
   WHERE abs(public.ST_Area(tg.geometry) - public.ST_Area(a.u)) / public.ST_Area(tg.geometry) > a.tol
      OR public.ST_Area(public.ST_Difference(a.u, tg.geometry)) / public.ST_Area(a.u) > 0.01;
  IF v_bad <> 0 THEN RAISE EXCEPTION 'POST: % district(s) whose areas do not match their TIGER polygon', v_bad; END IF;

  -- partition: no two areas of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N)
  SELECT count(*) INTO v_bad FROM _ta a JOIN _ta b ON a.parent_geo = b.parent_geo AND a.geo_id < b.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X0002'
    JOIN essentials.geofence_boundaries gb ON gb.geo_id = b.geo_id AND gb.mtfcc = 'X0002'
   WHERE public.ST_Intersects(ga.geometry, gb.geometry)
     AND public.ST_Area(public.ST_Intersection(ga.geometry, gb.geometry)) > 1e-7;
  IF v_bad <> 0 THEN RAISE EXCEPTION 'POST: % area pair(s) overlap', v_bad; END IF;

  -- END TO END: an interior point of each area reaches, on this board, exactly its own member plus the
  -- board's at-large holdovers (via the lookup's MTFCC mapping: X0002 and G5400/G5410 -> SCHOOL)
  SELECT count(*) INTO v_bad FROM _ta me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X0002'
   WHERE COALESCE((SELECT string_agg(DISTINCT och.politician_id::text, ',' ORDER BY och.politician_id::text)
             FROM essentials.geofence_boundaries gb
             JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL'
             JOIN essentials.offices o ON o.district_id = d.id
             JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
             JOIN essentials.politicians p ON p.id = och.politician_id AND p.is_active AND p.is_incumbent
            WHERE gb.mtfcc IN ('X0002','G5400','G5410')
              AND (d.geo_id = me.parent_geo OR d.geo_id LIKE me.parent_geo || '-ta-%')
              AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry))), '')
         IS DISTINCT FROM
         COALESCE((SELECT string_agg(x, ',' ORDER BY x) FROM (
             SELECT me.holder_pid::text AS x WHERE me.holder_pid IS NOT NULL
             UNION SELECT h.holder_pid::text FROM _hold h WHERE h.parent_geo = me.parent_geo) z), '');
  IF v_bad <> 0 THEN RAISE EXCEPTION 'POST: % area(s) do not return exactly their own trustee at an interior point', v_bad; END IF;

  -- no seat became invisible except the 6 fresh ones, which are flagged vacant
  SELECT count(*) INTO v_n FROM essentials.offices_missing_terms m JOIN essentials.offices o ON o.id = m.office_id
   WHERE NOT COALESCE(o.is_vacant, false);
  IF v_n <> (SELECT missing_unflagged FROM _ca0161_base) THEN
    RAISE EXCEPTION 'POST: unflagged offices_missing_terms moved from % to %', (SELECT missing_unflagged FROM _ca0161_base), v_n; END IF;

  RAISE NOTICE 'CA_0161 applied: 22 boards / 110 trustee areas -- 103 seats moved onto their member''s area, 1 vacant seat moved, 6 new vacant area seats (Palmdale, Keppel), 6 at-large holdovers kept on the whole-district row';
END $$;

COMMIT;
